<?php
namespace App\Http\Controllers;use App\Models\Designation;use Illuminate\Http\Request;class DesignationController extends Controller{function index(){return view('refs.index',['title'=>'Designations','items'=>Designation::paginate(30),'route'=>'designations']);}function create(){return view('refs.form',['item'=>new Designation,'route'=>'designations']);}function store(Request $r){Designation::create($r->validate(['name'=>'required','status'=>'nullable','type'=>'nullable','remarks'=>'nullable']));return redirect()->route('designations.index');}function edit(Designation $designation){return view('refs.form',['item'=>$designation,'route'=>'designations']);}function update(Request $r,Designation $designation){$designation->update($r->all());return redirect()->route('designations.index');}function destroy(Designation $designation){$designation->delete();return back();}}
